1	import { readdir, rmdir, stat, unlink } from "node:fs/promises";
2	import { homedir } from "node:os";
3	import { join } from "node:path";
4	import { inArray } from "drizzle-orm";
5	import type { HostDb } from "../../../db";
6	import { terminalSessions } from "../../../db/schema";
7	import { type AgentLifecycleEventType, mapEventType } from "../../../events";
8	import type {
9		TerminalAgentId,
10		TerminalAgentStore,
11	} from "../../../terminal-agents";
12	
13	/**
14	 * (BUS-RESYNC) One terminal's durable agent status, as the host knows it.
15	 * `pendingPermission` is deliberately separate from `lastEventType`: the Python
16	 * notify hook rewrites red-clearing events to `SubagentActive` while a question
17	 * marker is present, so the binding's `lastEventType` alone LOSES the permission
18	 * truth — a terminal blocked on an AskUserQuestion commonly reads
19	 * `SubagentActive` here. The marker is the only durable record of the red.
20	 */
21	export interface AgentStatusSnapshotRow {
22		terminalId: string;
23		originWorkspaceId: string;
24		agentId: TerminalAgentId;
25		lastEventType: AgentLifecycleEventType;
26		lastEventAt: number;
27		/**
28		 * `true`/`false` are answers; `null` means the marker directory could not be
29		 * READ (see `hasPendingQuestionMarker`) and the renderer must leave the
30		 * permission axis exactly as it found it.
31		 */
32		pendingPermission: boolean | null;
33	}
34	
35	/**
36	 * (BUS-RESYNC) (GHOST-TERMINAL) What the host can say about its terminals.
37	 *
38	 * `rows` is what it knows is LIVE. `knownTerminalIds` is every terminal id it
39	 * has a `terminal_sessions` row for AT ALL, whatever the status — the
40	 * difference between the two is the only thing that licenses the renderer to
41	 * clear a dot. A pane can hold a re-minted terminalId the host has never seen
42	 * (live case: pane terminal fc7ffd00 in workspace f85bc39c — every
43	 * `notifications.hook` POST for it returned `ignored: true`, and its only dot
44	 * came from the desktop's Electron fallback painting the store locally). Such a
45	 * ghost is absent from `rows` for a reason that has nothing to do with its
46	 * agent finishing, so "absent" alone would destroy a legitimate dot on every
47	 * reconnect. Present in `knownTerminalIds` but not in `rows` = positively
48	 * disowned; absent from both = never known, hands off.
49	 *
50	 * `knownTerminalIds` is INTERSECTED with the caller's `candidateTerminalIds`
51	 * when it sends them, so "absent from both" keeps its meaning for every
52	 * terminal the caller asked about and answers nothing about the rest.
53	 */
54	export interface AgentStatusSnapshot {
55		rows: AgentStatusSnapshotRow[];
56		knownTerminalIds: string[];
57		/**
58		 * (BUS-RESYNC) This host's wall clock when the snapshot was built, so the
59		 * renderer can express its OWN session start in the clock that stamped
60		 * `lastEventAt`. Every timestamp in `rows` is host-clock; the renderer's
61		 * cold-start seed boundary is renderer-clock, and comparing the two across a
62		 * relay (or a laptop that resumed with a corrected clock) misdates the
63		 * boundary by the skew in either direction. Elapsed time measured inside one
64		 * process is skew-free, so the renderer anchors to its process start and
65		 * translates: `hostNow - (rendererNow - rendererProcessStart)`.
66		 *
67		 * Captured BEFORE the marker reads below rather than after: an earlier
68		 * `hostNow` yields an earlier boundary, and an earlier boundary seeds fewer
69		 * rows away — erring toward showing a green the user may have already seen
70		 * rather than swallowing one they have not.
71		 */
72		hostNow: number;
73	}
74	
75	/**
76	 * (ASKQ-MARKER-READ) The same path segment guard the marker writers and the
77	 * companion reader apply before building a marker path — an id that fails it
78	 * could otherwise become a traversal.
79	 */
80	const SAFE_MARKER_SEGMENT = /^[A-Za-z0-9_-]+$/;
81	
82	/**
83	 * (ASKQ-MARKER-READ) (MANUAL-DISMISS) The askq marker directory for a terminal,
84	 * or `null` when the id could not have produced one.
85	 *
86	 * The `SAFE_MARKER_SEGMENT` test lives INSIDE this function rather than at each
87	 * call site so that no caller can hold a path built from an unvalidated id.
88	 * The reader's mistake would be a wrong dot; `clearPendingQuestionMarkers`
89	 * UNLINKS what it finds here, so a traversal would delete arbitrary files.
90	 * Returning `null` makes "we never wrote a marker for this id" the only value
91	 * an unsafe id can produce, and every caller has to decide what to do with it.
92	 */
93	export function askqMarkerDir(terminalId: string): string | null {
94		if (!SAFE_MARKER_SEGMENT.test(terminalId)) return null;
95		return join(
96			homedir(),
97			".superset",
98			"agent-subagent-running",
99			`${terminalId}.askq`,
100		);
101	}
102	
103	/**
104	 * (MANUAL-DISMISS) What one terminal's manual dismissal actually did to disk.
105	 *
106	 * `removed` and `survivors` are owner FILE NAMES (`_main`, a sanitized subagent
107	 * id). A non-empty `survivors` is the load-bearing half: an owner file is on
108	 * disk after the sweep — because it postdates the click, because it could not be
109	 * read, or because it appeared while the sweep ran — so a question the user has
110	 * not seen is pending and the red must stay up.
111	 */
112	export interface ClearedQuestionMarkers {
113		removed: string[];
114		survivors: string[];
115	}
116	
117	/**
118	 * (MANUAL-DISMISS) The one filesystem call this fence's verdict turns on,
119	 * injectable so its ENOENT / unknown-error branches and the create race below
120	 * can be driven deterministically. Production passes nothing and gets
121	 * `node:fs/promises`.
122	 */
123	export interface ClearMarkersDeps {
124		stat(path: string): Promise<{ mtimeMs: number }>;
125	}
126	
127	/**
128	 * (MANUAL-DISMISS) Remove the askq owners that existed when the user clicked
129	 * "Clear Status", and only those.
130	 *
131	 * Manual dismissal is the one action licensed to drop a red the snapshot would
132	 * otherwise re-assert forever (`(LEAKED-ASKQ-OWNER)` explains why nothing
133	 * host-side can prove a leak, so the user is the evidence). But the click is not
134	 * licensed to drop a question the agent raised in the meantime, and the window
135	 * is real: the tRPC round trip plus the readdir is long enough for a hook to
136	 * land. `dismissStartedAtMs` is captured by the CALLER before any deletion and
137	 * fences every owner individually — the Python hook writes the owner file
138	 * synchronously before it returns the `PermissionRequest`, so an owner whose
139	 * mtime is not OLDER than the click is proof of a question the user has not
140	 * seen. The comparison is strict in one direction only: an owner written in the
141	 * SAME millisecond as the click cannot be shown to predate it, so it survives
142	 * (`mtimeMs >= dismissStartedAtMs`) and only a provably older owner is deleted.
143	 *
144	 * THE LISTING IS READ TWICE, and the second read is not a nicety. The fence can
145	 * judge only what the first `readdir` returned, while the stat/unlink loop is
146	 * awaited — long enough for a hook to create an owner the loop never sees. The
147	 * final re-`readdir` is therefore the authority on `survivors`: ANYTHING still
148	 * present when the loop ends is a survivor, whether it was created during the
149	 * loop or recreated after its unlink, because "there is an owner file on disk
150	 * right now" is exactly what the next snapshot read finds and re-asserts a red
151	 * for. Without it `pendingAfter: false` is a claim about a listing that is
152	 * already out of date.
153	 *
154	 * Failure directions, all chosen to keep a red rather than invent a dismissal:
155	 *
156	 *  - an id that fails the path guard removes NOTHING (we never wrote for it, and
157	 *    a path built from it would be a traversal);
158	 *  - `ENOENT` on the directory is a successful no-op — the markers are already
159	 *    gone, which is exactly the state the caller asked for;
160	 *  - any OTHER readdir error THROWS, on both reads. An unreadable filesystem is
161	 *    not a successful dismissal, and reporting one would leave the renderer
162	 *    clearing a dot that the next resync re-asserts;
163	 *  - `ENOENT` from a `stat` counts the owner as REMOVED. It is the one stat
164	 *    failure that is positive evidence — the file provably no longer exists
165	 *    (answered or reaped mid-operation), which is the very end state this
166	 *    function exists to reach — and reporting it as a survivor invented a
167	 *    `pendingAfter: true` for a marker nothing can read back;
168	 *  - any OTHER `stat` failure leaves the owner in place and reports it as a
169	 *    survivor. Unknown is not evidence, the same direction the reader takes at
170	 *    `findOwnersOlderThanSession`.
171	 *
172	 * Owners are unlinked one at a time (never a recursive directory remove) and the
173	 * directory itself is dropped only when the final read finds it empty, so a
174	 * surviving owner keeps both its file and the directory the next reader looks
175	 * in.
176	 */
177	export async function clearPendingQuestionMarkers(
178		terminalId: string,
179		dismissStartedAtMs: number,
180		deps: ClearMarkersDeps = { stat },
181	): Promise<ClearedQuestionMarkers> {
182		const dir = askqMarkerDir(terminalId);
183		if (dir === null) {
184			console.warn(
185				"[notifications] refusing to clear askq markers for an unsafe terminal id",
186				{ terminalId },
187			);
188			return { removed: [], survivors: [] };
189		}
190	
191		let owners: string[];
192		try {
193			owners = await readdir(dir);
194		} catch (error) {
195			if ((error as NodeJS.ErrnoException).code === "ENOENT") {
196				return { removed: [], survivors: [] };
197			}
198			throw error;
199		}
200	
201		const removed: string[] = [];
202		const survivors: string[] = [];
203		for (const owner of owners) {
204			const path = join(dir, owner);
205			/** `null` = the file provably no longer exists, so there is no age to judge. */
206			let mtimeMs: number | null;
207			try {
208				mtimeMs = (await deps.stat(path)).mtimeMs;
209			} catch (error) {
210				if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
211					// Unknown age: not evidence the user has seen it. Keep the red.
212					console.warn(
213						"[notifications] askq owner could not be stat'd during dismissal — keeping it",
214						{ terminalId, owner, error },
215					);
216					survivors.push(owner);
217					continue;
218				}
219				// Answered or reaped between the readdir and here: gone is the end state
220				// this function is asking for, so it counts as removed rather than as an
221				// invented pending question.
222				mtimeMs = null;
223			}
224			if (mtimeMs !== null && mtimeMs >= dismissStartedAtMs) {
225				// Not provably older than the click. The user has not seen this question.
226				survivors.push(owner);
227				continue;
228			}
229			try {
230				await unlink(path);
231			} catch (error) {
232				if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
233				// Answered or reaped between the stat and here — the dismissal's
234				// intended end state, reached by somebody else.
235			}
236			removed.push(owner);
237		}
238	
239		// The authority on what is pending NOW. Everything above judged one listing
240		// taken before an awaited loop; an owner created during that loop is invisible
241		// to it, and reporting `survivors` from it alone tells the renderer to clear a
242		// dot that a marker on disk re-asserts on the next resync.
243		let remaining: string[];
244		try {
245			remaining = await readdir(dir);
246		} catch (error) {
247			if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
248			// Somebody removed the whole directory under us. Nothing is pending.
249			remaining = [];
250		}
251		for (const owner of remaining) {
252			if (!survivors.includes(owner)) survivors.push(owner);
253		}
254	
255		if (remaining.length === 0) {
256			// Best effort, and deliberately never fatal: the directory is a container,
257			// not the truth. An empty one reads as "no question" either way, and a
258			// racing hook may legitimately have just recreated an owner inside it.
259			await rmdir(dir).catch(() => {});
260		}
261	
262		return { removed, survivors };
263	}
264	
265	/**
266	 * (ASKQ-MARKER-READ) Is a question currently pending on this terminal? True
267	 * when `~/.superset/agent-subagent-running/<terminalId>.askq/` holds at least
268	 * one owner file (`_main` for a main-loop question, a sanitized subagent id
269	 * otherwise — the companion's `askqMarkerExists` reads the same directory one
270	 * owner at a time; the resync cares only that SOMEONE is asking).
271	 *
272	 * DELIBERATELY un-aged. `_MARKER_STALE_SECONDS` (12h) in the Python hook
273	 * governs RUN-DIR markers, whose mtime is refreshed by every PostToolUse; an
274	 * askq owner is touched once at creation and removed only by an answer, an
275	 * exact SubagentStop, a turn boundary or SessionEnd, and the hook's reaper
276	 * explicitly refuses to age it out (pane-map-hook.ts `_reap_stale_markers`)
277	 * because a legitimately blocked agent produces no tool activity at all.
278	 * Capping by mtime here would therefore replay a question left pending
279	 * overnight as plain yellow — the exact swallowed red this snapshot exists to
280	 * restore.
281	 *
282	 * Returns `null` when the directory exists but cannot be read: an unknown
283	 * filesystem is not evidence of "no question", and reporting `false` there
284	 * would silently downgrade every pending red on the host.
285	 *
286	 * (LEAKED-ASKQ-OWNER) A leaked owner — the hook process killed between writing
287	 * the marker and the answer, a Claude session SIGKILLed with no SessionEnd —
288	 * re-asserts red on every reconnect for as long as the terminal lives. There is
289	 * deliberately NO reap here, because nothing host-side can prove a leak:
290	 *
291	 *  - the owner files are EMPTY, and their names are `_main` or a sanitized
292	 *    subagent id, so they carry no session identity to match `agentSessionId`
293	 *    against;
294	 *  - binding liveness is already enforced upstream (`store.list()` is the
295	 *    liveness-joined read), so a marker for a dead terminal never reaches here;
296	 *  - mtime-vs-`binding.startedAt` looks like a session-boundary fence, but the
297	 *    ONLY way a marker survives into a new session is the SessionStart hook not
298	 *    running (it calls `_clear_dir` on the askq dir). In that same scenario the
299	 *    binding's `startedAt` is pinned by whichever later event did post — which
300	 *    can be AFTER a genuinely-open question was marked — so the fence would
301	 *    drop live reds in exactly the case it was meant to clean up.
302	 *
303	 * So the ambiguity is LOGGED and the red is kept: a stale red is a question the
304	 * user dismisses, a dropped red is an agent blocked forever with a green dot.
305	 * The hook clears the directory on the next SessionStart, abort or SessionEnd.
306	 *
307	 * Async throughout: this runs inside a tRPC query on the host-service event
308	 * loop, never on the desktop main thread.
309	 */
310	async function hasPendingQuestionMarker(
311		terminalId: string,
312		sessionStartedAt: number,
313	): Promise<boolean | null> {
314		// An id we would never have written a marker for is definitively absent.
315		const dir = askqMarkerDir(terminalId);
316		if (dir === null) return false;
317		let owners: string[];
318		try {
319			owners = await readdir(dir);
320		} catch (error) {
321			if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
322			console.error(
323				"[notifications] askq marker read FAILED — pending-question state unknown",
324				{ terminalId, error },
325			);
326			return null;
327		}
328		if (owners.length === 0) return false;
329	
330		// (LEAKED-ASKQ-OWNER) Diagnostic only — never a reap. See the note above for
331		// why an owner older than the binding's session start is suspicious but not
332		// provably dead.
333		const suspect = await findOwnersOlderThanSession(
334			dir,
335			owners,
336			sessionStartedAt,
337		);
338		if (suspect.length > 0) {
339			console.warn(
340				"[notifications] askq owner(s) predate this terminal's agent session — a LEAKED marker would pin red forever; keeping the red (see LEAKED-ASKQ-OWNER)",
341				{ terminalId, sessionStartedAt, owners: suspect },
342			);
343		}
344		return true;
345	}
346	
347	/**
348	 * (LEAKED-ASKQ-OWNER) Owner files whose mtime predates the binding's session
349	 * start, described for the log. A failed stat is reported as unknown rather
350	 * than suspicious — an unreadable marker is not evidence of anything.
351	 */
352	async function findOwnersOlderThanSession(
353		dir: string,
354		owners: string[],
355		sessionStartedAt: number,
356	): Promise<string[]> {
357		const suspect: string[] = [];
358		for (const owner of owners) {
359			try {
360				const stats = await stat(join(dir, owner));
361				if (stats.mtimeMs < sessionStartedAt) {
362					suspect.push(`${owner}@${Math.round(stats.mtimeMs)}`);
363				}
364			} catch {
365				// Raced removal or an unreadable entry: says nothing either way.
366			}
367		}
368		return suspect;
369	}
370	
371	/**
372	 * (BUS-RESYNC) Every live terminal-agent binding plus its marker-derived
373	 * pending-question state, alongside every terminal id this host has a session
374	 * row for. Bindings come from the liveness-joined store read, so a terminal
375	 * that has exited is already unrepresentable; the renderer clears stale axes
376	 * only for terminals that are in `knownTerminalIds` and NOT in `rows` (see
377	 * `AgentStatusSnapshot`).
378	 */
379	export async function buildAgentStatusSnapshot(
380		store: TerminalAgentStore,
381		db: HostDb,
382		candidateTerminalIds?: string[],
383	): Promise<AgentStatusSnapshot> {
384		// Deliberately first: see `AgentStatusSnapshot.hostNow` for why the earliest
385		// defensible reading is the conservative one.
386		const hostNow = Date.now();
387		const bindings = store.list();
388		const rows = await Promise.all(
389			bindings.map(async (binding) => {
390				const lastEventType = mapEventType(binding.lastEventType);
391				if (!lastEventType) {
392					console.warn(
393						"[notifications] agent status snapshot: unmappable lastEventType",
394						{
395							terminalId: binding.terminalId,
396							lastEventType: binding.lastEventType,
397						},
398					);
399					return null;
400				}
401				const row: AgentStatusSnapshotRow = {
402					terminalId: binding.terminalId,
403					originWorkspaceId: binding.workspaceId,
404					agentId: binding.agentId,
405					lastEventType,
406					lastEventAt: binding.lastEventAt,
407					pendingPermission: await hasPendingQuestionMarker(
408						binding.terminalId,
409						binding.startedAt,
410					),
411				};
412				return row;
413			}),
414		);
415		// DELIBERATELY unfiltered by status: the question this answers is "has this
416		// host ever minted this terminal", and an ended or disposing session is
417		// still a terminal the host owns and may legitimately disown. Filtering by
418		// `active` here would reclassify every finished terminal as a ghost and
419		// freeze its dots forever.
420		//
421		// Scoped to the caller's candidates when it supplies them. Rows are deleted
422		// only when a workspace is destroyed, so the unscoped read grows without
423		// bound and was shipped in full on every reconnect — while the only
424		// question the renderer's sweep asks is "is THIS terminal known", over the
425		// tens of terminals it holds state for. An absent input keeps the full list
426		// for callers that have no candidate set.
427		const knownTerminalIds = (
428			candidateTerminalIds === undefined
429				? db.select({ id: terminalSessions.id }).from(terminalSessions).all()
430				: candidateTerminalIds.length === 0
431					? []
432					: db
433							.select({ id: terminalSessions.id })
434							.from(terminalSessions)
435							.where(inArray(terminalSessions.id, candidateTerminalIds))
436							.all()
437		).map((session) => session.id);
438		return {
439			rows: rows.filter((row): row is AgentStatusSnapshotRow => row !== null),
440			knownTerminalIds,
441			hostNow,
442		};
443	}
444

