297				};
298			}
299	
300			const agent = normalizeAgentIdentity(input.agent);
301			// The persisted binding is the source of truth for whether this hook is a
302			// genuine active-to-terminal transition. Capture it before recordEvent
303			// replaces its last-event fields below — and, since it carries this
304			// terminal's last instant, it is also the anchor the monotonic stamp
305			// below is derived from.
306			const previousBinding = ctx.terminalAgentStore.get(input.terminalId);
307			const occurredAt = nextLifecycleInstantMs(
308				Date.now(),
309				previousBinding?.lastEventAt,
310			);
311	
312			ctx.eventBus.broadcastAgentLifecycle({
313				workspaceId: terminalSession.originWorkspaceId,
314				eventType,
315				terminalId: input.terminalId,
316				...(agent ? { agent } : {}),
317				occurredAt,
318			});
