321				terminalId: input.terminalId,
322				workspaceId: terminalSession.originWorkspaceId,
323				eventType,
324				...(agent?.agentId ? { agentId: agent.agentId } : {}),
325				...(agent?.sessionId ? { agentSessionId: agent.sessionId } : {}),
326				...(agent?.definitionId ? { definitionId: agent.definitionId } : {}),
327				occurredAt,
328			});
