336				payload: input,
337				terminalId: input.terminalId,
338				workspaceId: terminalSession.originWorkspaceId,
339				occurredAt,
340			});
341			forwardCompanionLifecycle({
342				payload: input,
343				eventType,
344				terminalId: input.terminalId,
345				workspaceId: terminalSession.originWorkspaceId,
346				occurredAtMs: occurredAt,
347				previousEventType: previousBinding?.lastEventType ?? null,
348				previousEventAtMs: previousBinding?.lastEventAt ?? null,
349			});
350	
351			// An agent began working in this workspace — nudge the linked task
352			// to In Progress.
353			if (eventType === "Start") {
354				markLinkedTaskStarted(ctx, terminalSession.originWorkspaceId);
355			}
356	
357			return { success: true, ignored: false as const };
358		}),
