import { appendFile, mkdir, readdir, readFile, stat, unlink } from "node:fs/promises";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import type { EventBus } from "../events/event-bus";
import { mapEventType } from "../events/map-event-type";
import type { TerminalAgentStore } from "./index";

/**
 * (STALE-WORKING-SWEEP) The dots are event-driven: superset-notify.py decides
 * yellow/green/blue/red INSIDE hook events, and every staleness reap it owns
 * ((BG-STALE) 15-min zombie teammates, the 12h leaked-marker backstop, the 6h
 * codex pid-reuse cap) can therefore only run when SOME hook event arrives.
 * When the last event of a session resolves to a working hold and the agent
 * then goes quiet — the exact shape of a finished agent-team session, whose
 * teammates Claude Code reports as background_tasks `status:"running"`
 * FOREVER — nothing ever re-evaluates and the terminal is yellow until the
 * app restarts (live 2026-08-22: two workspaces pinned yellow for hours after
 * their chats finished; dot-decisions.log showed the final decisions were
 * SubagentActive holds and then silence).
 *
 * This sweep is the structural backstop the hook cannot be: it runs on the
 * host-service clock, not the agent's. Every SWEEP_INTERVAL_MS it looks at
 * each LIVE binding whose last event resolved to a working state
 * (Start / SubagentActive) and has not changed for STALE_AFTER_MS, and
 * corroborates real quiescence against the same on-disk truth the hook
 * maintains (all under `~/.superset/agent-subagent-running/`, the HARDCODED
 * homedir root the snapshot reader also uses):
 *
 *  - `<t>.askq/` non-empty        -> a question is pending; NEVER touch a red.
 *  - `<t>/` any marker fresh      -> subagent activity inside the window; keep.
 *  - `<t>.bgactive` fresh         -> teammate activity inside the window; keep.
 *  - a codex-companion job JSON for this binding's agent session with status
 *    queued/running touched <6h   -> delegated work on its OWN API; keep.
 *
 * Only when EVERY hold is provably cold does it finalize the turn: broadcast +
 * record `Stop` (or release a parked `.pendingfailure` as `Failed`, consuming
 * the marker exactly like the hook's own DEFERRED-FAILURE release, so an API
 * abort is still never swallowed). A wrong green here self-corrects on the
 * next real hook event — any PostToolUse/SubagentStart re-asserts working —
 * while the state it repairs cannot self-correct at all, which is the whole
 * trade. Every finalization is loud: console.warn plus a line in the same
 * `~/.superset/logs/dot-decisions.log` the Python hook writes, so one file
 * still tells the full story of every dot decision.
 *
 * The threshold is deliberately generous: 30 minutes with ZERO hook events is
 * far beyond any real working gap (an active agent streams PostToolUse
 * constantly; a long think or compaction stays well under it), so a sweep
 * finalization is essentially always a stuck hold, and the log line proves it
 * either way.
 */
const SWEEP_INTERVAL_MS = 5 * 60_000;
const STALE_AFTER_MS = 30 * 60_000;
const CODEX_JOB_FRESH_MS = 6 * 60 * 60_000;

const MARKER_ROOT = () => join(homedir(), ".superset", "agent-subagent-running");

/** Mirrors the Python hook's marker-path guard (SAFE_MARKER_SEGMENT). */
const SAFE_SEGMENT = /^[A-Za-z0-9_-]+$/;

async function newestMtimeMs(dir: string): Promise<number | null> {
	// Newest entry mtime, or null when the directory is missing/empty. Any
	// unreadable entry counts as "fresh now" — unknown is not evidence of
	// quiescence, so it must keep the hold.
	let entries: string[];
	try {
		entries = await readdir(dir);
	} catch {
		return null;
	}
	let newest: number | null = null;
	for (const entry of entries) {
		try {
			const stats = await stat(join(dir, entry));
			if (newest === null || stats.mtimeMs > newest) newest = stats.mtimeMs;
		} catch {
			return Date.now();
		}
	}
	return newest;
}

async function fileMtimeMs(path: string): Promise<number | null> {
	try {
		return (await stat(path)).mtimeMs;
	} catch {
		return null;
	}
}

/**
 * Port of the hook's `_codex_job_active` freshness half (status queued/running
 * + job JSON touched inside the cap). The pid probe is deliberately omitted:
 * this runs on a 30-minute-stale binding, where a job file untouched for the
 * whole window plus the 6h cap is the decision boundary the hook itself
 * documents, and a false "active" here only keeps a yellow one more sweep.
 */
async function codexJobActive(agentSessionId: string): Promise<boolean> {
	const roots = [
		{
			root: join(homedir(), ".claude", "plugins", "data"),
			// codex*/state/*/jobs/*.json
			depth: ["codex", "state-any", "jobs"] as const,
		},
		{
			root: join(tmpdir(), "codex-companion"),
			// */jobs/*.json
			depth: ["any", "jobs-only"] as const,
		},
	];
	const jobDirs: string[] = [];
	try {
		for (const { root, depth } of roots) {
			let level1: string[];
			try {
				level1 = await readdir(root);
			} catch {
				continue;
			}
			for (const first of level1) {
				if (depth[0] === "codex" && !first.startsWith("codex")) continue;
				if (depth[0] === "codex") {
					const stateRoot = join(root, first, "state");
					let states: string[];
					try {
						states = await readdir(stateRoot);
					} catch {
						continue;
					}
					for (const state of states) {
						jobDirs.push(join(stateRoot, state, "jobs"));
					}
				} else {
					jobDirs.push(join(root, first, "jobs"));
				}
			}
		}
		const now = Date.now();
		for (const jobDir of jobDirs) {
			let jobs: string[];
			try {
				jobs = await readdir(jobDir);
			} catch {
				continue;
			}
			for (const job of jobs) {
				if (!job.endsWith(".json")) continue;
				const path = join(jobDir, job);
				try {
					const stats = await stat(path);
					if (now - stats.mtimeMs >= CODEX_JOB_FRESH_MS) continue;
					const record = JSON.parse(await readFile(path, "utf8")) as {
						sessionId?: string;
						status?: string;
					};
					if (record.sessionId !== agentSessionId) continue;
					if (record.status === "queued" || record.status === "running") {
						return true;
					}
				} catch {
					// Mid-write or unreadable: skip this file; the next sweep retries.
				}
			}
		}
	} catch {
		// An unreadable store proves nothing; treat as no hold (the marker
		// checks above are the primary evidence, and the next real event
		// re-asserts truth).
	}
	return false;
}

/**
 * Same file the Python hook's `_decision_log` writes, same line shape, so a
 * stuck dot keeps ONE audit trail across both producers. Best-effort.
 */
async function appendDecisionLog(
	terminalId: string,
	sessionId: string | undefined,
	eventType: string,
	reason: string,
): Promise<void> {
	try {
		const dir = join(homedir(), ".superset", "logs");
		await mkdir(dir, { recursive: true });
		const line = `${new Date().toISOString()} terminal=${terminalId} session=${sessionId ?? "None"} eventType=${eventType} ${reason}\n`;
		await appendFile(join(dir, "dot-decisions.log"), line, "utf8");
	} catch {
		// The broadcast is the load-bearing half; a lost log line is acceptable.
	}
}

/**
 * Decide one binding. Returns the eventType to finalize with, or null to
 * leave the binding alone. Exported for tests.
 */
export async function evaluateStaleWorkingBinding(args: {
	terminalId: string;
	agentSessionId?: string;
	staleAfterMs?: number;
	nowMs?: number;
}): Promise<{ eventType: "Stop" | "Failed"; reason: string } | null> {
	const staleAfterMs = args.staleAfterMs ?? STALE_AFTER_MS;
	const now = args.nowMs ?? Date.now();
	if (!SAFE_SEGMENT.test(args.terminalId)) return null;
	const root = MARKER_ROOT();

	// A pending question is a red; the sweep may never touch it.
	try {
		const owners = await readdir(join(root, `${args.terminalId}.askq`));
		if (owners.length > 0) return null;
	} catch {
		// Missing dir = no pending question.
	}

	const runMarker = await newestMtimeMs(join(root, args.terminalId));
	if (runMarker !== null && now - runMarker < staleAfterMs) return null;

	const bgActive = await fileMtimeMs(join(root, `${args.terminalId}.bgactive`));
	if (bgActive !== null && now - bgActive < staleAfterMs) return null;

	if (args.agentSessionId && (await codexJobActive(args.agentSessionId))) {
		return null;
	}

	const pendingFailurePath = join(root, `${args.terminalId}.pendingfailure`);
	if ((await fileMtimeMs(pendingFailurePath)) !== null) {
		// (DEFERRED-FAILURE) release the parked abort instead of greening past
		// it — consumed exactly once, mirroring the hook's own release paths.
		try {
			await unlink(pendingFailurePath);
		} catch {
			// Raced with a hook release; that release announced it already.
			return null;
		}
		return {
			eventType: "Failed",
			reason:
				"STALE-SWEEP FAILED: deferred StopFailure released, no events and no live holds (host-service sweep)",
		};
	}

	return {
		eventType: "Stop",
		reason:
			"STALE-SWEEP GREEN: no hook events and no live holds for the stale window (host-service sweep)",
	};
}

/**
