						nowMs: now,
					});
				} catch (error) {
					console.warn(
						`[terminal-agents] stale-working sweep failed to evaluate ${binding.terminalId}; leaving it untouched`,
						error,
					);
					continue;
				}
				if (verdict === null) continue;
				// Re-read: an event that landed while this pass awaited disk must
				// win — it is newer truth than the snapshot this loop iterated.
				const current = store.get(binding.terminalId);
