# evidence is now CUMULATIVE: every named non-fork Agent spawn scanned
# since the fresh-session boundary credits its description once, and a
# first-seen row batch may consume that credit whenever it fits — still
# causal (credits exist only for spawns observed inside this session's own
# scan chain, never from a cold offset-0 replay), still conservative (a
# batch larger than the unconsumed credit binds nothing, and consumed
# credit can never be spent twice).
if not partial_tail and loaded_cache:
    for spawn_name, spawn_description, _ in spawns:
        if spawn_description:
            spawn_credits.setdefault(spawn_description, []).append(spawn_name)
    # Bounded: at most 16 credits per description and the 64 newest
    # descriptions overall. Insertion order is oldest-first, so trimming
    # from the front forgets the stalest credits; a forgotten credit only
    # means that row stays yellow (safe direction).
    for description in list(spawn_credits):
        if len(spawn_credits[description]) > 16:
            spawn_credits[description] = spawn_credits[description][-16:]
    while len(spawn_credits) > 64:
        spawn_credits.pop(next(iter(spawn_credits)))
    new_rows_by_description = {}
    for entry_id, raw_description in entry_descriptions.items():
        if not entry_id or entry_id in trusted_ids:
            continue
        if entry_id in previously_seen:
            continue
        description = _team_description_key(raw_description)
        if description:
            new_rows_by_description.setdefault(description, []).append(entry_id)
    for description, row_ids in new_rows_by_description.items():
        credits = spawn_credits.get(description, [])
        if not credits or len(row_ids) > len(credits):
            continue
        # One credited spawn + one row binds exactly; more credited names
        # than rows binds the batch to ALL of them (ambiguity keeps the
        # whole candidate set, exactly like the old same-delta batch rule).
        causal_names = sorted(set(credits))
        del credits[: len(row_ids)]
        if not credits:
            spawn_credits.pop(description, None)
        for entry_id in row_ids:
            entry_names[entry_id] = causal_names
            trusted_ids.add(entry_id)

