export async function evaluateStaleWorkingBinding(args: {
	terminalId: string;
	agentSessionId?: string;
	staleAfterMs?: number;
	nowMs?: number;
}): Promise<{
	eventType: "Stop" | "Failed";
	pendingFailurePath?: string;
	reason: string;
} | null> {
	const staleAfterMs = args.staleAfterMs ?? STALE_AFTER_MS;
	const now = args.nowMs ?? Date.now();
	if (!SAFE_SEGMENT.test(args.terminalId)) return null;
	const root = MARKER_ROOT();

	// A pending question is a red; the sweep may never touch it — and an
	// UNREADABLE marker dir is not "no question", so it holds too.
	try {
		const owners = await readdir(join(root, `${args.terminalId}.askq`));
		if (owners.length > 0) return null;
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code !== "ENOENT") return null;
	}

	// POSITIVE turn-end evidence is required. A binding stuck in a working
	// state proves nothing about the MAIN loop: an agent deep inside one long
	// quiet stretch (a usage-limit wait, a long MCP/network tool, a non-Claude
	// CLI) posts no hook for the duration and writes no marker at all, so
	// marker silence alone would green live work. The `.mainstopped` sentinel
	// is the hook's own durable record that the main turn ENDED while a hold
	// was still live — exactly the stuck shape this sweep exists to finalize
	// (every hold result now keeps it, see (SENTINEL-HOLD)). No sentinel, no
	// finalization.
	const sentinel = await statMarker(
		join(root, `${args.terminalId}.mainstopped`),
	);
	if (sentinel.kind !== "mtime") return null;

	// Run markers own the hook's own 12h window (see the file comment): a
	// subagent inside ONE long tool call refreshes nothing, and a shorter
	// timer here would repeat the false-green the hook already learned from.
	const runMarker = await newestRunMarker(join(root, args.terminalId));
	if (runMarker.kind === "error") return null;
	if (
		runMarker.kind === "mtime" &&
		now - runMarker.mtimeMs < RUN_MARKER_WINDOW_MS
	) {
		return null;
	}

	const compacting = await statMarker(join(root, `${args.terminalId}.compacting`));
	if (compacting.kind === "error") return null;
	if (
		compacting.kind === "mtime" &&
		now - compacting.mtimeMs < COMPACT_WINDOW_MS
	) {
		return null;
	}

	const bgActive = await statMarker(join(root, `${args.terminalId}.bgactive`));
	if (bgActive.kind === "error") return null;
	if (bgActive.kind === "mtime" && now - bgActive.mtimeMs < staleAfterMs) {
		return null;
	}

	if (args.agentSessionId && (await codexJobActive(args.agentSessionId))) {
		return null;
	}

	const pendingFailurePath = join(root, `${args.terminalId}.pendingfailure`);
	const pendingFailure = await statMarker(pendingFailurePath);
	if (pendingFailure.kind === "error") return null;
	if (pendingFailure.kind === "mtime") {
		// (DEFERRED-FAILURE) release the parked abort instead of greening past
		// it. The marker is consumed by the COMMIT path, after the re-read
		// guard, so an event landing mid-sweep can never lose the abort.
		return {
			eventType: "Failed",
			pendingFailurePath,
			reason:
				"STALE-SWEEP FAILED: deferred StopFailure released, no events and no live holds (host-service sweep)",
		};
	}

	return {
		eventType: "Stop",
		reason:
			"STALE-SWEEP GREEN: no hook events and no live holds for the stale window (host-service sweep)",
	};
}

/**
 * Start the periodic sweep. Returns a stop function. Mirrors
 * `startTerminalReaper`'s shape: unref'd interval, re-entrancy guard, every
 * failure contained per pass.
 */

