async function codexJobActive(agentSessionId: string): Promise<boolean> {
	const roots = [
		{
			root: join(homedir(), ".claude", "plugins", "data"),
			// codex*/state/*/jobs/*.json
			codexShape: true,
		},
		{
			root: join(tmpdir(), "codex-companion"),
			// */jobs/*.json
			codexShape: false,
		},
	];
	const jobDirs: string[] = [];
	try {
		for (const { root, codexShape } of roots) {
			let level1: string[];
			try {
				level1 = await readdir(root);
			} catch {
				continue;
			}
			for (const first of level1) {
				if (codexShape) {
					if (!first.startsWith("codex")) continue;
					const stateRoot = join(root, first, "state");
					let states: string[];
					try {
						states = await readdir(stateRoot);
					} catch {
						continue;
					}
					for (const state of states) {
						jobDirs.push(join(stateRoot, state, "jobs"));
					}
				} else {
					jobDirs.push(join(root, first, "jobs"));
				}
			}
		}
		const now = Date.now();
		for (const jobDir of jobDirs) {
			let jobs: string[];
			try {
				jobs = await readdir(jobDir);
			} catch {
				continue;
			}
			for (const job of jobs) {
				if (!job.endsWith(".json")) continue;
				const path = join(jobDir, job);
				let fresh = false;
				try {
					fresh = now - (await stat(path)).mtimeMs < CODEX_JOB_FRESH_MS;
				} catch {
					continue; // gone between readdir and stat — not a job any more
				}
				if (!fresh) continue;
				try {
					const record = JSON.parse(await readFile(path, "utf8")) as {
						sessionId?: string;
						status?: string;
					};
					if (record.sessionId !== agentSessionId) continue;
					if (record.status === "queued" || record.status === "running") {
						return true;
					}
				} catch {
					// Fresh but unreadable/mid-write: cannot rule it out — hold.
					return true;
				}
			}
		}
	} catch {
		// An unreadable store proves nothing either way; the marker checks are
		// the primary evidence and the next real event re-asserts truth.
	}
	return false;
}

